docker run -d --name scan-lab -p 8080:8080 -e SPRING_PROFILES_ACTIVE=secure spring-scan-testbed:latest
# Verify only allowlisted beans are registered
curl http://localhost:8080/actuator/beans | jq '.contexts[].beans | keys | length'
